<script setup lang="ts">
import { encodeSearch, parseSearch } from '../frontend/layers/core/composables/taskState'
const route=useRoute(), router=useRouter(); const initial=parseSearch(route.query); const state=reactive(initial); const results=[{id:'api',title:'Google同期API',body:'競合処理',genre:'開発',priority:'HIGH',deadline:'1週間以内'},{id:'docs',title:'運用手順',body:'Google認証',genre:'運用',priority:'MEDIUM',deadline:'1か月以内'}]
