</script>
<template><div class="page"><span class="eyebrow">Search</span><h1>検索</h1><div class="search-controls card"><label>フリーワード<input v-model="state.q" type="search" placeholder="title・bodyを検索" /></label><fieldset><legend>ジャンル（OR）</legend><label><input v-model="state.genres" type="checkbox" value="開発" /> 開発</label><label><input v-model="state.genres" type="checkbox" value="運用" /> 運用</label></fieldset><label>優先度<select v-model="state.priority"><option value="">すべて</option><option value="high">HIGH</option><option value="medium">MEDIUM</option><option value="low">LOW</option></select></label><label>期限<select v-model="state.deadline"><option value="">すべて</option><option value="today">今日まで</option><option value="tomorrow">明日まで</option><option value="week">1週間以内</option><option value="month">1か月以内</option><option value="later">それ以上</option></select></label></div><div class="table-wrap card"><table><thead><tr><th>Task</th><th>本文</th><th>Genre</th><th>Priority</th><th>Deadline</th></tr></thead><tbody><tr v-for="task in results" :key="task.id"><td><NuxtLink :to="`/tasks/${task.id}`" target="_blank">{{ task.title }}</NuxtLink></td><td>{{ task.body }}</td><td>{{ task.genre }}</td><td>{{ task.priority }}</td><td>{{ task.deadline }}</td></tr></tbody></table></div></div></template>
